#include "ApiClient.hpp"
#include "AccessService.hpp"
#include "../config/GeoBRConfig.hpp"
#include <fmt/format.h>
namespace geobr {using geode::utils::web::WebRequest;using geode::utils::web::WebResponse;
void ApiClient::configure(WebRequest&r,std::chrono::seconds timeout){r.header("Accept","application/json").header("x-geobr-version",ClientVersion).userAgent(std::string("GeoBR-Mod/")+ClientVersion).timeout(timeout).certVerification(true).followRedirects(true);}
geode::utils::web::WebFuture ApiClient::get(std::string_view ep,QueryParams const&p){WebRequest r;configure(r,GeoBRConfig::RequestTimeout);for(auto const&[k,v]:p)r.param(k,v);return r.get(GeoBRConfig::endpointUrl(ep));}
geode::utils::web::WebFuture ApiClient::post(std::string_view ep,matjson::Value const&b){WebRequest r;configure(r,GeoBRConfig::RequestTimeout);r.header("Content-Type","application/json").bodyJSON(b);return r.post(GeoBRConfig::endpointUrl(ep));}
geode::utils::web::WebFuture ApiClient::getAuthorized(std::string url,std::string_view token,QueryParams const&p,std::chrono::seconds timeout){WebRequest r;configure(r,timeout);r.header("Authorization",fmt::format("Bearer {}",token));for(auto const&[k,v]:p)r.param(k,v);return r.get(std::move(url));}
geode::utils::web::WebFuture ApiClient::getSupabase(std::string url,QueryParams const&p){WebRequest r;configure(r,GeoBRConfig::RequestTimeout);auto key=GeoBRConfig::supabasePublishableKey();r.header("apikey",key);if(key.starts_with("eyJ"))r.header("Authorization",fmt::format("Bearer {}",key));for(auto const&[k,v]:p)r.param(k,v);return r.get(std::move(url));}
geode::utils::web::WebFuture ApiClient::getBinary(std::string url){WebRequest r;configure(r,std::chrono::seconds{20});r.header("Accept","application/octet-stream, application/xml, text/xml, application/zip");return r.get(std::move(url));}
geode::utils::web::WebFuture ApiClient::postAuthorized(std::string url,std::string_view token,matjson::Value const&b,std::chrono::seconds timeout){WebRequest r;configure(r,timeout);r.header("Authorization",fmt::format("Bearer {}",token)).header("Content-Type","application/json").bodyJSON(b);return r.post(std::move(url));}
geode::utils::web::WebFuture ApiClient::postSupabaseAuthorized(std::string url,std::string_view token,matjson::Value const&b,std::string_view prefer){WebRequest r;configure(r,GeoBRConfig::RequestTimeout);r.header("apikey",GeoBRConfig::supabasePublishableKey()).header("Authorization",fmt::format("Bearer {}",token)).header("Content-Type","application/json").header("Prefer",std::string(prefer)).bodyJSON(b);return r.post(std::move(url));}
ApiJsonResult ApiClient::decodeJson(WebResponse const&r){if(!r.ok()){if(r.cancelled())return{.error="A requisicao foi cancelada. Tente novamente."};auto d=std::string(r.errorMessage());if(d.empty())d="servidor indisponivel";if(d.size()>100)d.resize(100);return{.error=fmt::format("Nao foi possivel conectar (HTTP {}): {}",r.code(),d)};}if(r.data().size()>GeoBRConfig::MaxResponseBytes)return{.error="A resposta do servidor e grande demais."};auto j=r.json();if(j.isErr())return{.error="O servidor enviou uma resposta invalida."};return{true,std::move(j).unwrap(),{}};}
std::optional<std::string> ApiClient::configurationError(){auto u=GeoBRConfig::apiBaseUrl();if(!GeoBRConfig::isSecureBackendUrl(u))return"Configure uma URL HTTPS valida para a API do GeoBR.";if(u==GeoBRConfig::DefaultApiBaseUrl)return"A API publica do GeoBR ainda nao foi configurada.";return std::nullopt;}
}
